INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5484310, 790716, 52472, '<td valign="top">Great processing, the lighting conditions of such a river shot are always difficult! The mossy green mood gives a sensation of a long time span, which works very well for integrity. Finally it''s a fantastic composition you could use as a textbook example! But enough praise, I don''t like your font :p</td>', 'Great processing, the lighting conditions of such a river shot are always difficult! The mossy green mood gives a sensation of a long time span, which works very well for integrity. Finally it''s a fantastic composition you could use as a textbook example! But enough praise, I don''t like your font :p', '2009-05-13 13:52:50.000000', NULL, 1),
(5484311, 790173, 106219, '<td valign="top">Too true.</td>', 'Too true.', '2009-05-13 13:53:01.000000', NULL, 1),
(5484313, 790595, 106219, '<td valign="top">I got goose bumps!</td>', 'I got goose bumps!', '2009-05-13 13:53:40.000000', NULL, 1),
(5484316, 790449, 106219, '<td valign="top">I wish this was in focus.</td>', 'I wish this was in focus.', '2009-05-13 13:54:20.000000', NULL, 1),
(5484318, 790030, 106219, '<td valign="top">This would be better if there was a baby or a toddler trying to make it up the steps.</td>', 'This would be better if there was a baby or a toddler trying to make it up the steps.', '2009-05-13 13:55:07.000000', NULL, 1),
(5484325, 790750, 106219, '<td valign="top">This would have been better without an obvious flash.</td>', 'This would have been better without an obvious flash.', '2009-05-13 13:57:42.000000', NULL, 1),
