(5490137, 790526, 23484, '<td valign="top">Great job. I like the diagonal feel to it.</td>', 'Great job. I like the diagonal feel to it.', '2009-05-17 14:04:55.000000', NULL, 1),
(5490138, 790410, 23484, '<td valign="top">Hey, they don''t look much older than me.</td>', 'Hey, they don''t look much older than me.', '2009-05-17 14:06:11.000000', NULL, 1),
(5490213, 790665, 102315, '<td valign="top">Very pretty picture but the font makes the smaller typed words a little harder to see.</td>', 'Very pretty picture but the font makes the smaller typed words a little harder to see.', '2009-05-17 16:14:53.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5490215, 790733, 102315, '<td valign="top">Like the message.</td>', 'Like the message.', '2009-05-17 16:15:43.000000', NULL, 1),
(5490216, 789130, 102315, '<td valign="top">Great one of a kind shot. How did you get a shot like this...I must know? Was this in an aquarium? I also like the message.</td>', 'Great one of a kind shot. How did you get a shot like this...I must know? Was this in an aquarium? I also like the message.', '2009-05-17 16:18:14.000000', NULL, 1),
(5490218, 790595, 102315, '<td valign="top">Great message. Also, as wonderful candid shot. Wish I could have seen this in the candid challenge. It would have done great there also.</td>', 'Great message. Also, as wonderful candid shot. Wish I could have seen this in the candid challenge. It would have done great there also.', '2009-05-17 16:19:26.000000', NULL, 1),
(5490219, 790505, 102315, '<td valign="top">The white specks are very distracting.</td>', 'The white specks are very distracting.', '2009-05-17 16:20:00.000000', NULL, 1),
(5490221, 790408, 102315, '<td valign="top">Very nice shot but I wish the word "excellence" was not over the actual picture. Makes it a little harder to read.</td>', 'Very nice shot but I wish the word "excellence" was not over the actual picture. Makes it a little harder to read.', '2009-05-17 16:20:53.000000', NULL, 1),
(5490225, 788879, 102315, '<td valign="top">Good photo just wish the text was not overlapping it. Takes away from the feel of a poster and draws my eyes away from the frog to quickly to see what''s going on with the text.</td>', 'Good photo just wish the text was not overlapping it. Takes away from the feel of a poster and draws my eyes away from the frog to quickly to see what''s going on with the text.', '2009-05-17 16:25:17.000000', NULL, 1),
(5490226, 790719, 105171, '<td valign="top">Nice capture.  Fitting caption.</td>', 'Nice capture.  Fitting caption.', '2009-05-17 16:27:50.000000', NULL, 1),
(5490227, 789841, 105171, '<td valign="top">Excellent capture and nice color.  Fitting caption.</td>', 'Excellent capture and nice color.  Fitting caption.', '2009-05-17 16:28:59.000000', NULL, 1),
(5490229, 790526, 105171, '<td valign="top">Nice capture and framing.</td>', 'Nice capture and framing.', '2009-05-17 16:30:39.000000', NULL, 1),
(5490231, 790762, 105171, '<td valign="top">Nice lively image. Great use of colors and framing.</td>', 'Nice lively image. Great use of colors and framing.', '2009-05-17 16:33:05.000000', NULL, 1),
(5490270, 790340, 78371, '<td valign="top">The colors in the photograph are really fantastic.</td>', 'The colors in the photograph are really fantastic.', '2009-05-17 17:14:03.000000', NULL, 1),
(5490405, 790716, 54033, '<td valign="top">Good! who said that 10</td>', 'Good! who said that 10', '2009-05-17 20:53:26.000000', NULL, 1),
(5490410, 790689, 54033, '<td valign="top">You are right, I especially hate the Aurora part. 10  for making fun of them</td>', 'You are right, I especially hate the Aurora part. 10  for making fun of them', '2009-05-17 20:55:49.000000', NULL, 1),
(5490478, 790144, 78371, '<td valign="top">I find myself wanting to get out of that red room as fast as possible. I guess one could say that it is motivating the viewer to go out into the world and explore.  I don''t know how well this will do here but I gave this photo an 8.</td>', 'I find myself wanting to get out of that red room as fast as possible. I guess one could say that it is motivating the viewer to go out into the world and explore.  I don''t know how well this will do here but I gave this photo an 8.', '2009-05-17 22:38:20.000000', NULL, 1),
(5490481, 789512, 78371, '<td valign="top">The selective saturation works well with this photograph, plus I am partial to flamingos anyway.  IMHO the composition would be a bit stronger if the tail feathers were not cut off.  8</td>', 'The selective saturation works well with this photograph, plus I am partial to flamingos anyway.  IMHO the composition would be a bit stronger if the tail feathers were not cut off.  8', '2009-05-17 22:43:09.000000', NULL, 1),
(5490482, 789964, 78371, '<td valign="top">great quote</td>', 'great quote', '2009-05-17 22:44:03.000000', NULL, 1),
(5490483, 790518, 78371, '<td valign="top">lol, that quote is fantastic. I also like the blue tone to the photograph as well.</td>', 'lol, that quote is fantastic. I also like the blue tone to the photograph as well.', '2009-05-17 22:45:18.000000', NULL, 1),
(5490507, 789512, 57447, '<td valign="top">Beautiful colors.</td>', 'Beautiful colors.', '2009-05-17 23:39:20.000000', NULL, 1),
(5490511, 790716, 57447, '<td valign="top">Good quote to complement great photo.</td>', 'Good quote to complement great photo.', '2009-05-17 23:41:59.000000', NULL, 1),
(5490520, 790767, 96881, '<td valign="top">I like the saying matching the photo, but I feel the title does not tie in as well with it.  I feel there needs to be a little more  of the dark ground to balance this photo.  You cropped too much of the lower part out for me.  It also feels like it is not straight as a result of the uneven ground.  For some reason, it feels like the left hand side is higher than it should be.<br/>Also, the border and the writing appear to be different colours.  I would have used the pink for both.  The orange looks a little boring and washed out, and not the bright, vibrant colour it should be.</td>', 'I like the saying matching the photo, but I feel the title does not tie in as well with it.  I feel there needs to be a little more  of the dark ground to balance this photo.  You cropped too much of the lower part out for me.  It also feels like it is not straight as a result of the uneven ground.  For some reason, it feels like the left hand side is higher than it should be.Also, the border and the writing appear to be different colours.  I would have used the pink for both.  The orange looks a little boring and washed out, and not the bright, vibrant colour it should be.', '2009-05-17 23:57:49.000000', NULL, 1),
(5490522, 790358, 96881, '<td valign="top">Hmmm, motivtaional poster?  Not really meeting the challenge here.<br/>On top of that, the photo looks much more like a snapshot than an intentionally composed photo.  The background elements are distracting. The black and white is good, but not really what would normally be seen int his type of challenge....</td>', 'Hmmm, motivtaional poster?  Not really meeting the challenge here.On top of that, the photo looks much more like a snapshot than an intentionally composed photo.  The background elements are distracting. The black and white is good, but not really what would normally be seen int his type of challenge....', '2009-05-17 23:59:21.000000', NULL, 1),
(5490526, 790575, 96881, '<td valign="top">nice photo, and nice overall combination.  The phrase and title match the photo and compliment each part well.<br/>The photo is good, but perhaps the sun being centred maybe isn''t the strongest thing.  Having it to one side, on the third line, may have helped against this, and given an even more broad range of colours.  Further to that, a little extra dark foreground would also have balanced this photo much more.<br/> <br/>Don''t know why you opted for the text colour being different from the border.  Having both of these in the blue would have kept the entire poster together more and given a more finished and professional look.</td>', 'nice photo, and nice overall combination.  The phrase and title match the photo and compliment each part well.The photo is good, but perhaps the sun being centred maybe isn''t the strongest thing.  Having it to one side, on the third line, may have helped against this, and given an even more broad range of colours.  Further to that, a little extra dark foreground would also have balanced this photo much more. Don''t know why you opted for the text colour being different from the border.  Having both of these in the blue would have kept the entire poster together more and given a more finished and professional look.', '2009-05-18 00:02:34.000000', NULL, 1),
(5490530, 790660, 96881, '<td valign="top">Different to many of the others, but a well executed poster.  I feel the subject and message are suited to the different presentation, and the overall submission looks very finished and professional. The presentation of this is exceptionally good.<br/>Lighting of the fruit has been done very well.  A few reflections on the apple and orange that maybe are a little distracting, but I like the lighting of the grapes and Banana''s, which I feel you got spot on.  The range of colours gives the poster an interesting look and the arrangement works very well.</td>', 'Different to many of the others, but a well executed poster.  I feel the subject and message are suited to the different presentation, and the overall submission looks very finished and professional. The presentation of this is exceptionally good.Lighting of the fruit has been done very well.  A few reflections on the apple and orange that maybe are a little distracting, but I like the lighting of the grapes and Banana''s, which I feel you got spot on.  The range of colours gives the poster an interesting look and the arrangement works very well.', '2009-05-18 00:05:01.000000', NULL, 1),
(5490536, 790340, 96881, '<td valign="top">An exceptional submission.  This looks professional, and something I could image seeing on peoples walls.  The photo matches the title and phrase very well.  I feel that the white for the border and writing in this case was the correct choice, as any other colour in the photo would have merged in somewhere in the border.  The photo has a lot of interesting elements, with the right depth of field and very interesting colours throughout.  A top class submission for this challenge, and one of my highest rated photos.</td>', 'An exceptional submission.  This looks professional, and something I could image seeing on peoples walls.  The photo matches the title and phrase very well.  I feel that the white for the border and writing in this case was the correct choice, as any other colour in the photo would have merged in somewhere in the border.  The photo has a lot of interesting elements, with the right depth of field and very interesting colours throughout.  A top class submission for this challenge, and one of my highest rated photos.', '2009-05-18 00:07:28.000000', NULL, 1),
(5490550, 790436, 96881, '<td valign="top">A very interesting submission.  A great idea, but the execution of the photo maybe didn''t quite do ity justice.  The flower looks way too fake for me, and I feel you lose a lot of the overall impact as a result of that.  The yellow I feel needed to be a strong, bold, bright yellow, and not the colour you have in this.  A vibrant colour would ahve made it stand out, and make a statement, above everything else.</td>', 'A very interesting submission.  A great idea, but the execution of the photo maybe didn''t quite do ity justice.  The flower looks way too fake for me, and I feel you lose a lot of the overall impact as a result of that.  The yellow I feel needed to be a strong, bold, bright yellow, and not the colour you have in this.  A vibrant colour would ahve made it stand out, and make a statement, above everything else.', '2009-05-18 00:09:44.000000', NULL, 1),
(5490561, 790719, 96881, '<td valign="top">The phrase suits the photo, but not quite the challenge.  Not really motivational, but rather a statement.  The overall presentation fo this also lets it down.  A border around the photo, and some more attention to the right choice of font would ahve made this look a lot more professional.<br/> <br/>The lighting reflections on the basket are a distraction.  as are a number of the elements in the background that you have tried to eliminate with the shallow depth of field, but this has not quite been successful in this case.</td>', 'The phrase suits the photo, but not quite the challenge.  Not really motivational, but rather a statement.  The overall presentation fo this also lets it down.  A border around the photo, and some more attention to the right choice of font would ahve made this look a lot more professional. The lighting reflections on the basket are a distraction.  as are a number of the elements in the background that you have tried to eliminate with the shallow depth of field, but this has not quite been successful in this case.', '2009-05-18 00:12:39.000000', NULL, 1),
(5490564, 790591, 96881, '<td valign="top">Interesting photo, but it does not appear as sharp as it should and there also appears to be noise throughout the photo which affects the overall presentation.  Further to that, the presentation of this doesn''t seem really there, the green border seems a little rushed, and not the correct shade.  The colour should have come from the photo to tie it all together.</td>', 'Interesting photo, but it does not appear as sharp as it should and there also appears to be noise throughout the photo which affects the overall presentation.  Further to that, the presentation of this doesn''t seem really there, the green border seems a little rushed, and not the correct shade.  The colour should have come from the photo to tie it all together.', '2009-05-18 00:14:30.000000', NULL, 1),
(5490572, 790526, 96881, '<td valign="top">Excellent photo composition for this, i like the overall placement, the diagonal composition, the scattered parts.  it all works for me in that sense.<br/>You chose the text and border colour from the photo, which normally is exactly the right thing to do.  However, in this case, maybe is makes everything a little too brown.  Would have to experiment with the colours to see if something worked better........<br/>The phrase is great, matches the photo, however the text size is too small, and I don''t think it should be capitalised.  Maybe script in a larger font would have worked so much better.  A great photo for this, but the overall presentation of this is not quite as good.</td>', 'Excellent photo composition for this, i like the overall placement, the diagonal composition, the scattered parts.  it all works for me in that sense.You chose the text and border colour from the photo, which normally is exactly the right thing to do.  However, in this case, maybe is makes everything a little too brown.  Would have to experiment with the colours to see if something worked better........The phrase is great, matches the photo, however the text size is too small, and I don''t think it should be capitalised.  Maybe script in a larger font would have worked so much better.  A great photo for this, but the overall presentation of this is not quite as good.', '2009-05-18 00:18:15.000000', NULL, 1),
(5490581, 790283, 99708, '<td valign="top">Where is the motivational message....</td>', 'Where is the motivational message....', '2009-05-18 00:21:38.000000', NULL, 1),
(5490587, 790665, 96881, '<td valign="top">A really good submission.  Very professional presentation and the choice of both the background colour and text/border is spot on.  That helps make this as one of the best overall submissions int hsi shallenge.<br/>Phrase/Title/Photo combination is great, and all compliment each other.  Photo is really good, simple, yet well executed, interesting without being overlly dominating, so perfect for this type of poster.<br/>Smallest thing.........offset the Quote author to the right more, and remove the brackets.......this is the only thing that makes me think this isn''t already for sale in shops...........excellent submission</td>', 'A really good submission.  Very professional presentation and the choice of both the background colour and text/border is spot on.  That helps make this as one of the best overall submissions int hsi shallenge.Phrase/Title/Photo combination is great, and all compliment each other.  Photo is really good, simple, yet well executed, interesting without being overlly dominating, so perfect for this type of poster.Smallest thing.........offset the Quote author to the right more, and remove the brackets.......this is the only thing that makes me think this isn''t already for sale in shops...........excellent submission', '2009-05-18 00:24:34.000000', NULL, 1),
(5490588, 790707, 99708, '<td valign="top">Cute picture, unfortunately the shadow is distracting</td>', 'Cute picture, unfortunately the shadow is distracting', '2009-05-18 00:25:11.000000', NULL, 1),
(5490595, 790443, 96881, '<td valign="top">On first galnce, I really like the photo, but as I look into it more, there are a number of things that catch my eye.  The tree on the left is blown to the left, making me tilt my head, and you have cropped off the very edge of it.  More space to the left was needed to balance this photo.  it is currently too far to the left in the frame to be the subject, yet is the most dominating part.  it needs to sit ont eh third line, prefeably the right third due to the lean.  Trees are cropped off on the right, which also makes it look unfinished.  Further to that, the writing just seems to blend in a little too much, rather than making the bold statement it should make......</td>', 'On first galnce, I really like the photo, but as I look into it more, there are a number of things that catch my eye.  The tree on the left is blown to the left, making me tilt my head, and you have cropped off the very edge of it.  More space to the left was needed to balance this photo.  it is currently too far to the left in the frame to be the subject, yet is the most dominating part.  it needs to sit ont eh third line, prefeably the right third due to the lean.  Trees are cropped off on the right, which also makes it look unfinished.  Further to that, the writing just seems to blend in a little too much, rather than making the bold statement it should make......', '2009-05-18 00:28:44.000000', NULL, 1),
(5490599, 790670, 96881, '<td valign="top">Interesting photo, and an interesting phrase.  I feel the colours in this shot could have benifited from some attention in Post processing,.  The photo appears to lack contrast, and some saturation adjustment could have made this stronger.  Not sure about the presentation.  I feel this would have been much more suited to the traditional motivational poster with black border, title (Trust) and the phrase underneath.....</td>', 'Interesting photo, and an interesting phrase.  I feel the colours in this shot could have benifited from some attention in Post processing,.  The photo appears to lack contrast, and some saturation adjustment could have made this stronger.  Not sure about the presentation.  I feel this would have been much more suited to the traditional motivational poster with black border, title (Trust) and the phrase underneath.....', '2009-05-18 00:30:58.000000', NULL, 1),
(5490604, 788817, 96881, '<td valign="top">This photo appears like a snapshot, all the way down to the feet int he background, whicha lso emphasised the rotation of the photo.  Distracting elements int he background, I don''t like the writing on the photo, I don''t understand why the title colour was chosen, and struggle to see the real relevance of this photo to the challenge</td>', 'This photo appears like a snapshot, all the way down to the feet int he background, whicha lso emphasised the rotation of the photo.  Distracting elements int he background, I don''t like the writing on the photo, I don''t understand why the title colour was chosen, and struggle to see the real relevance of this photo to the challenge', '2009-05-18 00:33:03.000000', NULL, 1),
(5490608, 790518, 96881, '<td valign="top">Humour, great.......I like the ideaof this, and feel that it works to a point.  Some extra attention to detail could have made this even stronger.  A border around the photo (small black and then the blue grey) and having the writing in the blue/grey of the photo.  A different font also would have helped.  these minor changes would have made a much more professional look to the submission.</td>', 'Humour, great.......I like the ideaof this, and feel that it works to a point.  Some extra attention to detail could have made this even stronger.  A border around the photo (small black and then the blue grey) and having the writing in the blue/grey of the photo.  A different font also would have helped.  these minor changes would have made a much more professional look to the submission.', '2009-05-18 00:35:09.000000', NULL, 1),
(5490620, 789421, 96881, '<td valign="top">It is.......the combination of colours you have used for this works very well, as the use of both the green and red highlight these in the photo.  I think the depth of field for the photo was too shallow, as I feel that having the right hand side of the plant blurred detracts from the overall image.  Hvaing this photo all crisp and clear I feel would have made a stronger statement</td>', 'It is.......the combination of colours you have used for this works very well, as the use of both the green and red highlight these in the photo.  I think the depth of field for the photo was too shallow, as I feel that having the right hand side of the plant blurred detracts from the overall image.  Hvaing this photo all crisp and clear I feel would have made a stronger statement', '2009-05-18 00:47:45.000000', NULL, 1),
(5490621, 789416, 96881, '<td valign="top">This photo is a combination of overexposed areas (the window) and underexposed (the room)  There are no correctly exposed areas in this photo.  The crop is not even, the subject is very uninteresting, the black and white processing doesn''t work.........</td>', 'This photo is a combination of overexposed areas (the window) and underexposed (the room)  There are no correctly exposed areas in this photo.  The crop is not even, the subject is very uninteresting, the black and white processing doesn''t work.........', '2009-05-18 00:49:01.000000', NULL, 1),
(5490623, 790722, 96881, '<td valign="top">A greater depth of field, having the entire flower in focus, I feel would have been a ctronger overall image.  As it is, too much of the overall image is out of focus,..........</td>', 'A greater depth of field, having the entire flower in focus, I feel would have been a ctronger overall image.  As it is, too much of the overall image is out of focus,..........', '2009-05-18 00:50:02.000000', NULL, 1),
(5490628, 790689, 96881, '<td valign="top">A political statement in a motivational challenge.  I feel this would have been much better suited in the de-motivational challenge due to the level of sarcasm applied...........The overall presentation is good, it lacks a really strong photo element though......</td>', 'A political statement in a motivational challenge.  I feel this would have been much better suited in the de-motivational challenge due to the level of sarcasm applied...........The overall presentation is good, it lacks a really strong photo element though......', '2009-05-18 00:51:55.000000', NULL, 1),
(5490629, 790449, 96881, '<td valign="top">A very wierd looking animal.......The colours in this are uninspiring, and could have been vastly improved in post processing, which could have made this a much stronger submission</td>', 'A very wierd looking animal.......The colours in this are uninspiring, and could have been vastly improved in post processing, which could have made this a much stronger submission', '2009-05-18 00:53:04.000000', NULL, 1),
(5490784, 790521, 96881, '<td valign="top">A great image for a poster, with some great colours in there.  That there is no strong subject in this image works very well, and ties in exceptionally well with the title and phrase.  This poster lacks the border that is common to these posters, and the choice of text colour doesn''t tie in well to the picture.  Adding these would then have made this look like one you could buy from a shop.</td>', 'A great image for a poster, with some great colours in there.  That there is no strong subject in this image works very well, and ties in exceptionally well with the title and phrase.  This poster lacks the border that is common to these posters, and the choice of text colour doesn''t tie in well to the picture.  Adding these would then have made this look like one you could buy from a shop.', '2009-05-18 02:46:24.000000', NULL, 1),
(5490821, 790365, 96881, '<td valign="top">A different idea.  I am really not sure about the black side borders.  To me they seem to make the rest of the picture look even lighter.  As a result, my first impression was overexposed, yet as you look closer, it is very high key, but the details for the most part are still, to an extent, preserved.<br/>The writing looks awkward by its positioning.  The right choice of colour, but it just doesn''t look right in that position, not that I can see a better spot though.......</td>', 'A different idea.  I am really not sure about the black side borders.  To me they seem to make the rest of the picture look even lighter.  As a result, my first impression was overexposed, yet as you look closer, it is very high key, but the details for the most part are still, to an extent, preserved.The writing looks awkward by its positioning.  The right choice of colour, but it just doesn''t look right in that position, not that I can see a better spot though.......', '2009-05-18 03:58:58.000000', NULL, 1),
(5490822, 789821, 96881, '<td valign="top">A nice photo, but it seems to me like I am missing the rest of the scene.  I feel I need more from this, on both sides, and even top and bottom.  I just seem to have a small piece of a great location, yet I am restricted in what I can see.......</td>', 'A nice photo, but it seems to me like I am missing the rest of the scene.  I feel I need more from this, on both sides, and even top and bottom.  I just seem to have a small piece of a great location, yet I am restricted in what I can see.......', '2009-05-18 04:00:46.000000', NULL, 1),
(5490824, 790721, 96881, '<td valign="top">Nice, a great picture with a humour aspect to it as well.  The entire shot is well composed and works really well.<br/>Not sure about the colour of the writing and border.  I feel it should have been the yellow from the sign, whereas this is a different yellow.  The brighter yellow would have tied it in a lot better.</td>', 'Nice, a great picture with a humour aspect to it as well.  The entire shot is well composed and works really well.Not sure about the colour of the writing and border.  I feel it should have been the yellow from the sign, whereas this is a different yellow.  The brighter yellow would have tied it in a lot better.', '2009-05-18 04:02:22.000000', NULL, 1),
(5490825, 790188, 96881, '<td valign="top">A great submission, in the true motivational poster style, and fitting of being a poster.  The image is interesting, without being overpowering, colourful without needing to be studied.  Exactly what these posters should be.  The choice of text colour and border is spot on, the size of text, the fonts, everything for this works and looks professional.  The placement of the person on the line of third is very good and helps this image work.  An excellent submission</td>', 'A great submission, in the true motivational poster style, and fitting of being a poster.  The image is interesting, without being overpowering, colourful without needing to be studied.  Exactly what these posters should be.  The choice of text colour and border is spot on, the size of text, the fonts, everything for this works and looks professional.  The placement of the person on the line of third is very good and helps this image work.  An excellent submission', '2009-05-18 04:03:02.000000', NULL, 1),
(5490826, 790716, 96881, '<td valign="top">Stunning........<br/>The words are brilliant, fit both the challenge and the photograph completely.......<br/>The image is perfect for a motivational poster.  Compliments the words exactly, well executed and the type of photo that is often seen on these.<br/> <br/>A great submission</td>', 'Stunning........The words are brilliant, fit both the challenge and the photograph completely.......The image is perfect for a motivational poster.  Compliments the words exactly, well executed and the type of photo that is often seen on these. A great submission', '2009-05-18 04:03:18.000000', NULL, 1),
(5491293, 790743, 105171, '<td valign="top">Excellent sharpness and very good use of DOF which gives a nice background.</td>', 'Excellent sharpness and very good use of DOF which gives a nice background.', '2009-05-18 13:37:55.000000', NULL, 1),
(5491319, 790199, 83313, '<td valign="top">Really nice bug shot, but I''m not sure what this is motivating me to do. Walk on someone Else''s back to achieve my goals?</td>', 'Really nice bug shot, but I''m not sure what this is motivating me to do. Walk on someone Else''s back to achieve my goals?', '2009-05-18 14:01:20.000000', NULL, 1),
(5491321, 790695, 83313, '<td valign="top">Had to think about this one for a minute to let the message sink in.</td>', 'Had to think about this one for a minute to let the message sink in.', '2009-05-18 14:02:52.000000', NULL, 1),
(5491328, 788976, 83313, '<td valign="top">Your caption works, but the photo gives it a twist that perhaps puts it in the de-motivational challenge. I think.</td>', 'Your caption works, but the photo gives it a twist that perhaps puts it in the de-motivational challenge. I think.', '2009-05-18 14:05:13.000000', NULL, 1),
(5491332, 790526, 83313, '<td valign="top">One of the best tie-in''s of the imamge and caption I have seen.</td>', 'One of the best tie-in''s of the imamge and caption I have seen.', '2009-05-18 14:06:32.000000', NULL, 1),
(5491339, 790358, 83313, '<td valign="top">Just seems a snapshot, and the slogan does not really motivate me in any way. However, seeing this guy chewing with his mouth open does motivate me to give this a low vote. Sorry to be so harsh, but this just does not work for me on any level.</td>', 'Just seems a snapshot, and the slogan does not really motivate me in any way. However, seeing this guy chewing with his mouth open does motivate me to give this a low vote. Sorry to be so harsh, but this just does not work for me on any level.', '2009-05-18 14:11:54.000000', NULL, 1),
